head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS20101.xml';
scwin.listRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();
scwin.vProcGubun = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.BND_APPL_ID = arrPar[0].BND_APPL_ID;
        scwin.objParam.BND_LIST_PROCS_TP_CD = arrPar[0].BND_LIST_PROCS_TP_CD;
        scwin.objParam.MKTACT_TP_CD = arrPar[0].MKTACT_TP_CD;
        scwin.objParam.SCREN_ID = arrPar[0].SCREN_ID;
    }
};



/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(txb_BndApplId) == '') {
        $c.win.alert("등록할 데이터가 없습니다.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_RefndDd) == '') {
        $c.win.alert("[환급일]을 입력하십시오.");
        edt_RefndDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_RefndDd, "환급일")) {
        return false;
    }
    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자')) return false;
    return true;
};


/********************************************** 
 * 함수명   : fn_save
 * 설명      : 연부과금 환급수수료 등록 (상장폐지(종목))
 ***********************************************/
scwin.fn_save = function() {
    if (!confirm("저장 하시겠습니까?")) return;
    var url = "/bns/ListBzAppl.do?method=createAnulfeeRefundFee";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&PARENT_SCREN_ID=" + scwin.objParam.SCREN_ID;
    url += "&MKTACT_TP_CD=" + scwin.objParam.MKTACT_TP_CD;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};
scwin.gform_onload = function() {
    $c.stf.showObj(lbl_info, false);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Input);

    //호출파라미터설정
    scwin.fn_SetParam();

    //연부과금 환급수수료 등록화면 조회	
    var dsNm = 'BNS_ANFEE_REFND';
    var qryId = '';
    qryId = 'lds.stf.bnscommon.select.listAnfeeRefnd';
    var param;
    param += '&{P}V_BND_APPL_ID=' + scwin.objParam.BND_APPL_ID;
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.objParam.BND_LIST_PROCS_TP_CD;
    if (scwin.objParam.SCREN_ID == 'ULDBNS20100.gfm') {
        scwin.vProcGubun = 'MOD';
    } else {
        scwin.vProcGubun = 'IN';
    }
    param += '&{P}V_GUBUN=' + scwin.vProcGubun;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};
scwin.dts_DtlInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    scwin.listRowCount = rowcount;
    //담당자명이 비어 있는 경우, 사용자 이름을 보여줌
    if ($c.stf.getObjectValue(txb_ChrgNm) == '') {
        $c.stf.setObjectValue(txb_ChrgNm, js_emp_nm);
    }
    edt_BndAnulfee.RightMargin = 5;
    edt_PassProfit.RightMargin = 5;
    edt_RepayAmt.RightMargin = 5;
    if (dts_DtlInfo.getCellData(1, "BND_MKTACT_TP_CD") == '311') {
        $c.stf.showObj(lbl_BndDelDd, false);
    } else if (dts_DtlInfo.getCellData(1, "BND_MKTACT_TP_CD") == '314') {
        $c.stf.showObj(lbl_AfchgRedmptDd, false);
        $c.stf.setObjectValue(edt_RedmptDd, $c.stf.getObjectValue(edt_StrtDd));
        $c.stf.showObj(lbl_FstRedmptDd, false); //최초상환일추가
        $c.stf.showObj(edt_FstRedmptDd, false); //최초상환일추가

    } else {
        $c.stf.showObj(lbl_BndDelDd, false);
        $c.stf.showObj(lbl_AfchgRedmptDd, false);
        $c.stf.showObj(edt_RedmptDd, false);
        $c.stf.showObj(lbl_FstRedmptDd, false); //최초상환일추가
        $c.stf.showObj(edt_FstRedmptDd, false); //최초상환일추가

        $c.stf.showObj(lbl_info, true);
    }
};
scwin.img_RefndDd_onclick = function() {
    popUpCalendar2(edt_RefndDd);
};
scwin.btn_Save_onclick = async function() {
    if (scwin.listRowCount == 0) return;
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return;
    if (scwin.objParam.MKTACT_TP_CD == "314" || scwin.objParam.SCREN_ID == "ULDBNS20100.gfm") {
        scwin.fn_save();
    } else {
        var prt = $c.frame.path("../");
        prt.dts_AnnulFee.ImportData(dts_DtlInfo.getRangeJSON(1, dts_DtlInfo.getTotalRow(), false));
        var arrPar = new Array();
        arrPar[0] = {
            REG_YN: "Y"
        };
        scwin.fn_SetPar(arrPar);
        await $c.frame.CloseFrame();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    $c.win.alert(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    var arrPar = new Array();
    arrPar[0] = {
        REG_YN: "Y"
    };
    scwin.fn_SetPar(arrPar);
    if (scwin.vProcGubun != 'MOD') {
        //연부과금환급에서 호출시 수정후 확인
        await $c.frame.CloseFrame();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.edt_BndAnulfee_OnKillFocus = function() {
    edt_BndAnulfee.RightMargin = 5;
};
scwin.edt_PassProfit_OnKillFocus = function() {
    edt_PassProfit.RightMargin = 5;
};
scwin.edt_RepayAmt_OnKillFocus = function() {
    edt_RepayAmt.RightMargin = 5;
};
